// grow grows the seed of a left-recursive leader from a failure: it evaluates the body again while
// the match gets longer, and returns the last longer result. A growth in a context takes its steps
// through the context, which may give them without evaluating the body. Outside a context, the form
// specialized for missing also drops the tokens that each adopted step inserted. A step holds the errors it
// recovered, and the entries they made are dropped from the record after it; the growth ends with the errors
// of its last result in place of the entries recorded since it began.
//
// Printed from Exec IR function grow of internal/ir/code/exec/compose, specialized for missing, typed, units.
func (p *TParser) grow(r *TRule, min int) (any, bool) {
	var bv any
	var bok bool
	rec := len(p.Recovered)
	{
		mm := p.MissingLen()
		g := p.growBegin(r.Rule, min)
		if g.ctx {
			for {
				if p.growMemoStep(&g) != nil {
					break
				}
				p.growIsolate(&g)
				p.Units++
				if p.Units > p.UnitsCheck {
					p.PollUnits()
				}
				v, ok := p.invoke(r, min)
				if !ok {
					p.Recovered = p.Recovered[:rec]
				}
				if (len(p.Recovered) - rec) > 0 {
					p.Units += uint64(len(p.Recovered) - rec)
					if p.Units > p.UnitsCheck {
						p.PollUnits()
					}
				}
				s := p.growKeepStep(&g, nil, v, ok, p.recSince(rec))
				p.Recovered = p.Recovered[:rec]
				if !p.growGrew(&g, s) {
					break
				}
				p.growAdoptStep(&g, s)
			}
		} else {
			for {
				p.Units++
				if p.Units > p.UnitsCheck {
					p.PollUnits()
				}
				v, ok := p.invoke(r, min)
				if !p.growLonger(&g, ok) {
					break
				}
				if (len(p.Recovered) - rec) > 0 {
					p.Units += uint64(len(p.Recovered) - rec)
					if p.Units > p.UnitsCheck {
						p.PollUnits()
					}
				}
				p.growAdopt(&g, nil, v, p.recSince(rec))
				p.Recovered = p.Recovered[:rec]
				p.ResetMissing(mm)
			}
		}
		best := p.growEnd(&g)
		p.Recovered = p.Recovered[:rec]
		p.ResetMissing(mm)
		if p.inserting() {
			p.replayMissing(best.ins, best.errs, true)
		} else {
			p.recAdd(best.errs)
		}
		bv = best.val
		bok = best.ok
	}
	return bv, bok
}

